package com.bank.qa.tddbdd;

import java.math.BigDecimal;

// Built via TDD at the UNIT level (small, testable, clear contract).
class TransferService {
    static class Result { final boolean ok; final String error;
            Result(boolean ok, String error) { this.ok = ok;
            this.error = error; } }

    // Unit logic: validate + compute. TDD drives each small behavior.
    Result transfer(BigDecimal fromBalance, BigDecimal amount) {
        if (amount == null || amount.signum() <= 0) return new Result(false, "Invalid amount");
        if (fromBalance.compareTo(amount) < 0) return new Result(false, "Insufficient balance");
        return new Result(true, null);
    }
}
