package com.bank.qa.tddbdd;

import java.math.BigDecimal;
import java.util.logging.*;

public class TddBddDemo {
    private static final Logger log = Logger.getLogger(TddBddDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new TddBddLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        TransferService svc = new TransferService();

        log.info("=== TDD layer: fast UNIT tests drive the implementation ===");
        unit("valid transfer ok",
            svc.transfer(new BigDecimal("1000000"), new BigDecimal("50000")).ok);
        unit("zero amount rejected",
            !svc.transfer(new BigDecimal("1000000"), BigDecimal.ZERO).ok);
        unit("overdraft rejected",
            !svc.transfer(new BigDecimal("1000"), new BigDecimal("50000")).ok);

        log.info("=== BDD layer: business-readable ACCEPTANCE scenario ===");
        log.info("GIVEN Rajesh balance 1000000  WHEN transfer 50000 to Priya  THEN success");
        TransferService.Result r = svc.transfer(new BigDecimal("1000000"), new BigDecimal("50000"));
        log.info("Acceptance -> " + (r.ok ? "PASS (behavior business agreed is met)" : "FAIL"));

        log.info("TDD builds the thing RIGHT (units correct); "
            + "BDD builds the RIGHT thing (behavior business agreed). Use BOTH.");
    }

    private static void unit(String name, boolean passed) {
        log.info((passed ? "GREEN " : "RED ") + name);
    }
}

// ─── Would be in TddBddLogFormatter.java in a real project ───
class TddBddLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
